'use strict';
// Coche: Mercedes-AMG GT3 Evo (2020)
// - Motor 6.2L V8 atmosférico AMG M159 con 550 CV y más de 650 Nm de par atronador.
// - Transmisión transaxle secuencial Hewland de 6 marchas con levas de fibra de carbono.
// - Parrilla Panamericana sobredimensionada, 'shark nose' y splitter frontal aerodinámico.
// - Rugido gutural atronador de carreras clásico de AMG V8 con estallidos en deceleración.
(() => {

const ATLAS_B64 = "data:image/png;base64,";
const BODY_V = "";
const BODY_I = "";
const GLASS_V = "";
const GLASS_I = "";
const WHEEL_V = "";
const WHEEL_I = "";

function b64ToF32(b64) {
  const bin = atob(b64);
  const buf = new ArrayBuffer(bin.length);
  const u8 = new Uint8Array(buf);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new Float32Array(buf);
}
function b64ToU32(b64) {
  const bin = atob(b64);
  const buf = new ArrayBuffer(bin.length);
  const u8 = new Uint8Array(buf);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new Uint32Array(buf);
}

WGSL["mat_mercedes_amg_gt3"] = `// Material Mercedes-AMG GT3 Evo
#include mesh_vert
@group(3) @binding(0) var tAtlas: texture_2d<f32>;

fn surf(in: V2F, ff: bool) -> Surface {
  var s = surfDefault(normalize(in.nrm));
  if (!ff) { s.normal = -s.normal; }

  let id = matId(in.mat);
  let p = in.ext.xyz;
  let uv = in.uv;

  let tx = textureSample(tAtlas, sLin, uv);

  if (id == 2u) {
    // Carrocería Mercedes Designo Selenite Grey Magno / Iridium Silver Metallic con decoración AMG flúor
    let basePaint = vec3f(0.68, 0.70, 0.72);
    let decalStrength = smoothstep(0.04, 0.15, max(tx.r, max(tx.g, tx.b)));
    s.albedo = mix(basePaint, tx.rgb, decalStrength);
    s.metal = mix(0.35, 0.08, decalStrength);
    s.rough = mix(0.18, 0.22, decalStrength);
    s.coat = mix(0.75, 0.25, decalStrength);
    s.ao = smoothstep(0.05, 0.45, p.y) * 0.35 + 0.65;
  } else if (id == 35u || id == 36u || id == 37u || id == 38u) {
    // Habitáculo de carreras GT3: jaula de seguridad FIA, bacquet y fibra de carbono
    s.albedo = vec3f(0.05, 0.05, 0.055);
    s.metal = 0.10;
    s.rough = 0.65;
  } else if (id == 46u || id == 47u || id == 48u) {
    // Llantas AMG GT3 forjadas multirradio en negro satinado
    s.albedo = vec3f(0.12, 0.12, 0.13);
    s.metal = 0.75;
    s.rough = 0.22;
    s.coat = 0.40;
  } else if (id == 6u || id == 23u) {
    // Ópticas delanteras LED multihaz (reflectores cromados y lupas 3D nítidas)
    s.albedo = tx.rgb;
    s.metal = 0.85;
    s.rough = 0.15;
    s.coat = 0.50;
    s.emissive = 0.0;
  } else if (id == 45u) {
    // Luces diurnas amarillas de resistencia 24h Nürburgring
    s.albedo = tx.rgb;
    s.emissive = 0.35;
    s.rough = 0.10;
  } else if (id == 7u || id == 8u) {
    // Pilotos traseros LED AMG estilizados
    s.albedo = tx.rgb;
    s.emissive = 0.85;
    s.rough = 0.10;
  } else if (id == 21u) {
    // Pinzas de freno AMG Brembo rojas
    s.albedo = vec3f(0.90, 0.05, 0.05);
    s.metal = 0.45;
    s.rough = 0.20;
    s.coat = 0.80;
  } else if (id == 3u || id == 52u) {
    // Fibra de carbono AMG Performance (splitter frontal Panamericana, difusor, alerón)
    s.albedo = vec3f(0.045, 0.045, 0.05);
    s.metal = 0.08;
    s.rough = 0.30;
    s.coat = 0.60;
  } else {
    s.albedo = tx.rgb;
    s.metal = 0.18;
    s.rough = 0.32;
  }

  return s;
}
`;

function loadAtlas() {
  const W = 2048, H = 2048;
  const tex = mkTex(W, H, 'rgba8unorm-srgb', TU.RT | TU.TB | TU.CD, { mipLevelCount: 7 });
  const initData = new Uint8Array(W * H * 4);
  initData.fill(220);
  G.dev.queue.writeTexture({ texture: tex }, initData, { bytesPerRow: W * 4 }, [W, H]);

  if (typeof Image !== 'undefined') {
    const img = new Image();
    img.src = ATLAS_B64;
    img.onload = () => {
      if (typeof createImageBitmap !== 'undefined') {
        createImageBitmap(img).then(bmp => {
          G.dev.queue.copyExternalImageToTexture({ source: bmp }, { texture: tex }, [W, H]);
          if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
        }).catch(() => {
          const cvs = document.createElement('canvas');
          cvs.width = W; cvs.height = H;
          const ctx2d = cvs.getContext('2d');
          ctx2d.drawImage(img, 0, 0);
          const id = ctx2d.getImageData(0, 0, W, H);
          G.dev.queue.writeTexture({ texture: tex }, id.data, { bytesPerRow: W * 4 }, [W, H]);
          if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
        });
      } else {
        const cvs = document.createElement('canvas');
        cvs.width = W; cvs.height = H;
        const ctx2d = cvs.getContext('2d');
        ctx2d.drawImage(img, 0, 0);
        const id = ctx2d.getImageData(0, 0, W, H);
        G.dev.queue.writeTexture({ texture: tex }, id.data, { bytesPerRow: W * 4 }, [W, H]);
        if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
      }
    };
  }
  return tex;
}

const CAR = {
  id: 'mercedes-amg-gt3-2020',
  name: 'Mercedes-AMG GT3 Evo',
  subtitle: '2020 GT3 Spec · 6.2L V8 atmosférico M159 · 550 CV',
  specs: '1285 kg · 550 CV · Hewland 6-vel seq · RWD · Shark Nose Aero',
  accent: '#c0c0c0',
  physics: {
    m: 1285, Izz: 1770, L: 2.630, a: 1.340, b: 1.290, tw: 1.69, h: 0.39, R: 0.340,
    mu: 1.71, B: 11.4, C: 1.52, driveF: 0.0,
    gears: [2.85, 2.05, 1.58, 1.27, 1.06, 0.89], final: 3.48, rev: 3.0, eff: 0.96,
    cdA: 0.68, crr: 0.010, brakeF: 0.60, halfW: 1.03, front: 2.48, rear: 2.46,
    clA: 0.94, aeroSplitF: 0.40,
    torqueBase: 420, torquePeak: 240, torqueDrop: 170, torquePeakStart: 0.50, torquePeakSpan: 4.8, torqueDropRpm: 7.5,
    shiftUpRpm: 7700, shiftDownRpm: 5600, revLimitRpm: 8000, maxRpm: 8200, idleRpm: 1100,
  },
  hud: { maxKmh: 335, maxRpm: 8.5, redlineRpm: 7.8 },
  wheelbase: 2.630, trackF: 1.698, trackR: 1.675, wheelR: 0.340,
  hubs: [
    [1.390, 0.340, -0.831],
    [1.390, 0.340, 0.831],
    [-1.240, 0.340, -0.831],
    [-1.240, 0.340, 0.831]
  ],
  slotBody: 0, slotWheel: [0, 0, 0, 0],
  tris: 0, _t: m4(), _t2: m4(), _t3: m4(), set: null, glass: null, atlasBG: null, fam: null,
  _z4: new Float32Array(4),
  inp: new Float64Array(2),

  build() {
    const fam = CAR.fam = mkFamily('car_mercedes_amg', { src: 'mat_mercedes_amg_gt3', noCube: true });
    CAR.slotBody = objSlot();
    for (let i = 0; i < 4; i++) CAR.slotWheel[i] = objSlot();

    const set = CAR.set = new MeshSet(fam);
    const glass = CAR.glass = new GlassSet();

    const mb = new MeshBuilder(1 << 19);
    const gl = new MeshBuilder(1 << 15);
    const w = new MeshBuilder(1 << 15);

    const bV = b64ToF32(BODY_V), bI = b64ToU32(BODY_I);
    const gV = b64ToF32(GLASS_V), gI = b64ToU32(GLASS_I);
    const wV = b64ToF32(WHEEL_V), wI = b64ToU32(WHEEL_I);

    const nbV = bV.length / 9;
    for (let i = 0; i < nbV; i++) {
      mb.mat(bV[i*9 + 8]);
      mb.v(bV[i*9], bV[i*9+1], bV[i*9+2], bV[i*9+3], bV[i*9+4], bV[i*9+5], bV[i*9+6], bV[i*9+7]);
    }
    for (let i = 0; i < bI.length; i += 3) mb.tri(bI[i], bI[i+1], bI[i+2]);

    const ngV = gV.length / 9;
    for (let i = 0; i < ngV; i++) {
      gl.v(gV[i*9], gV[i*9+1], gV[i*9+2], gV[i*9+3], gV[i*9+4], gV[i*9+5], gV[i*9+6], gV[i*9+7]);
    }
    for (let i = 0; i < gI.length; i += 3) gl.tri(gI[i], gI[i+1], gI[i+2]);

    const nwV = wV.length / 9;
    for (let i = 0; i < nwV; i++) {
      w.mat(wV[i*9 + 8]);
      w.v(wV[i*9], wV[i*9+1], wV[i*9+2], wV[i*9+3], wV[i*9+4], wV[i*9+5], wV[i*9+6], wV[i*9+7]);
    }
    for (let i = 0; i < wI.length; i += 3) w.tri(wI[i], wI[i+1], wI[i+2]);

    CAR.tris = mb.ni / 3 + gl.ni / 3;
    set.add(mb.upload(), CAR.slotBody, 3);
    glass.add_(gl.upload(), CAR.slotBody);

    const wm = w.upload();
    CAR.tris += 4 * w.ni / 3;
    for (let i = 0; i < 4; i++) set.add(wm, CAR.slotWheel[i], 3);

    const tex = loadAtlas();
    R.drawables.push({
      draw(pass, ctx) {
        if (ctx.kind === KIND.SHADOW && ctx.cascade === 3) return;
        if (!CAR.atlasBG) {
          if (!fam.bgl3) return;
          CAR.atlasBG = G.dev.createBindGroup({ layout: fam.bgl3, entries: [{ binding: 0, resource: tex.createView() }] });
        }
        pass.setBindGroup(3, CAR.atlasBG);
        set.draw(pass, ctx);
      },
    });
    R.transparents.push(glass);

    m4ident(CAR._t);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    console.log('[Mercedes-AMG GT3 Evo] Inicializado con éxito. Triángulos:', CAR.tris);
  },

  place(body, spin, susp) {
    const steer = CAR.inp[0];
    const t = CAR._t2;
    objPrev(CAR.slotBody).set(objModel(CAR.slotBody));
    objModel(CAR.slotBody).set(body);
    for (let i = 0; i < 4; i++) {
      const sl = CAR.slotWheel[i], h = CAR.hubs[i], left = (i & 1) === 0;
      objPrev(sl).set(objModel(sl));
      const a = -(i < 2 ? steer : 0) + (left ? PI : 0), c = Math.cos(a), sn = Math.sin(a);
      const g = left ? spin[i] : -spin[i], cg = Math.cos(g), sg = Math.sin(g);
      t[0] = c * cg; t[1] = sg; t[2] = -sn * cg; t[3] = 0;
      t[4] = -c * sg; t[5] = cg; t[6] = sn * sg; t[7] = 0;
      t[8] = sn; t[9] = 0; t[10] = c; t[11] = 0;
      t[12] = h[0]; t[13] = h[1] + susp[i]; t[14] = h[2]; t[15] = 1;
      m4mul(objModel(sl), body, t);
    }
  }
};

CARS.register(CAR);
})();
